package com.sarzilsazibpharmacy;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.io.ByteArrayInputStream;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.Base64;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;

/**
 * Main dashboard for Sarzil Sazib Pharmacy.
 * The pharmacy photograph is embedded in this Java source file.
 *
 * Put this file in package: com.sarzilsazibpharmacy
 * Run: MainDashboard.java
 */
public class MainDashBoard extends JFrame {

    private static final Color PAGE = new Color(250, 248, 242);
    private static final Color NAVY = new Color(8, 28, 72);
    private static final Color GOLD = new Color(232, 183, 55);
    private static final Color OLIVE = new Color(145, 145, 55);
    private static final Color BLUE = new Color(20, 65, 145);
    private static final Color MAROON = new Color(128, 45, 55);

    // Embedded image data: no separate image file or image path is required.
    private static final String[] PHARMACY_IMAGE_PARTS = {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            ""
    };

    public MainDashBoard() {
        setTitle("SARZIL SAZIB PHARMACY");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(1450, 900);
        setMinimumSize(new Dimension(1100, 720));
        setLocationRelativeTo(null);
        buildUI();
    }

    private void buildUI() {
        JPanel page = new JPanel(new BorderLayout(0, 16));
        page.setBackground(PAGE);
        page.setBorder(new EmptyBorder(18, 22, 20, 22));

        JPanel brand = new JPanel();
        brand.setOpaque(false);
        brand.setLayout(new BoxLayout(brand, BoxLayout.Y_AXIS));

        JLabel title = new JLabel("SARZIL SAZIB PHARMACY");
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        title.setFont(new Font("Arial", Font.BOLD, 38));
        title.setForeground(BLUE);

        JLabel phone = new JLabel("01772004646");
        phone.setAlignmentX(Component.CENTER_ALIGNMENT);
        phone.setFont(new Font("Arial", Font.BOLD, 27));
        phone.setForeground(new Color(105, 115, 35));

        JLabel address = new JLabel("Uposhohor, Bogura");
        address.setAlignmentX(Component.CENTER_ALIGNMENT);
        address.setFont(new Font("Arial", Font.BOLD, 20));
        address.setForeground(MAROON);

        brand.add(title);
        brand.add(Box.createVerticalStrut(5));
        brand.add(phone);
        brand.add(Box.createVerticalStrut(2));
        brand.add(address);
        page.add(brand, BorderLayout.NORTH);

        // Full rectangular area: sidebar on the left, image on the right,
        // with no gap. Sidebar uses about 38% of the available width.
        JPanel mainArea = new JPanel(new BorderLayout(0, 0));
        mainArea.setBackground(PAGE);
        mainArea.setBorder(BorderFactory.createLineBorder(new Color(190, 150, 70), 2));

        JPanel sidebar = buildSidebar();
        sidebar.setPreferredSize(new Dimension(560, 620));
        mainArea.add(sidebar, BorderLayout.WEST);

        JPanel imagePanel = buildImagePanel();
        mainArea.add(imagePanel, BorderLayout.CENTER);

        mainArea.addComponentListener(new java.awt.event.ComponentAdapter() {
            @Override
            public void componentResized(java.awt.event.ComponentEvent e) {
                int sidebarWidth = (int) (mainArea.getWidth() * 0.38);
                sidebar.setPreferredSize(new Dimension(Math.max(420, sidebarWidth), mainArea.getHeight()));
                mainArea.revalidate();
            }
        });

        page.add(mainArea, BorderLayout.CENTER);
        setContentPane(page);
    }

    private JPanel buildSidebar() {
        JPanel outer = new JPanel(new BorderLayout());
        outer.setBackground(NAVY);
        outer.setBorder(new EmptyBorder(0, 0, 0, 0));

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(NAVY);

        addModuleSection(content, "1. STOCK MANAGEMENT & SEARCH",
                new String[]{"ADD STOCK", "UPDATE STOCK", "DELETE STOCK", "STOCK ALERT", "SEARCH"},
                new String[]{"StockManagement"}, "Stock Management");

        addModuleSection(content, "2. SALES MANAGEMENT & INVOICE",
                new String[]{"SALE INFORMATION", "CUSTOMER INFORMATION", "ADD SALE",
                        "UPDATE SALE", "INVOICE", "DUE COLLECT", "DELETE SALE"},
                new String[]{"SalesManagement"}, "Sales Management");

        addModuleSection(content, "3. TOTAL SALES REPORT",
                new String[]{"SEARCH SALE & FILTER", "SALE REPORT OF MEDICINE", "EXPORT CSV"},
                new String[]{"TotalSalesReport", "Totalsale", "TotalSale"}, "Total Sales Report");

        addModuleSection(content, "4. CUSTOMER MANAGEMENT",
                new String[]{"ADD CUSTOMER", "UPDATE CUSTOMER", "DELETE CUSTOMER", "SEARCH CUSTOMER"},
                new String[]{"CustomerManagement"}, "Customer Management");

        JScrollPane scroll = new JScrollPane(content,
                JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
                JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.setViewportBorder(BorderFactory.createEmptyBorder());
        scroll.getViewport().setBackground(NAVY);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        outer.add(scroll, BorderLayout.CENTER);
        return outer;
    }

    private void addModuleSection(JPanel content, String buttonText, String[] bullets,
                                  String[] classNames, String displayName) {
        JButton button = new JButton(buttonText);
        button.setFont(new Font("Arial", Font.BOLD, 16));
        button.setForeground(Color.BLACK);
        button.setBackground(GOLD);
        button.setOpaque(true);
        button.setFocusPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setAlignmentX(Component.LEFT_ALIGNMENT);
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 52));
        button.setPreferredSize(new Dimension(520, 52));
        button.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(185, 132, 20), 1),
                new EmptyBorder(7, 8, 7, 8)));
        button.addActionListener(e -> openModule(classNames, displayName));
        content.add(button);
        content.add(Box.createVerticalStrut(7));

        // These bullet labels are decorative text, not buttons.
        for (String item : bullets) {
            JLabel bullet = new JLabel("\u2022  " + item);
            bullet.setFont(new Font("Arial", Font.BOLD, 12));
            bullet.setForeground(OLIVE);
            bullet.setAlignmentX(Component.LEFT_ALIGNMENT);
            bullet.setBorder(new EmptyBorder(2, 10, 2, 2));
            bullet.setFocusable(false);
            bullet.setCursor(Cursor.getDefaultCursor());
            content.add(bullet);
        }
        content.add(Box.createVerticalStrut(13));
    }

    private JPanel buildImagePanel() {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(Color.WHITE);
        panel.setBorder(BorderFactory.createEmptyBorder());

        JLabel imageLabel = new JLabel();
        imageLabel.setHorizontalAlignment(SwingConstants.CENTER);
        imageLabel.setVerticalAlignment(SwingConstants.CENTER);
        panel.add(imageLabel, BorderLayout.CENTER);

        try {
            StringBuilder encodedImage = new StringBuilder();
            for (String part : PHARMACY_IMAGE_PARTS) encodedImage.append(part);
            byte[] imageBytes = Base64.getDecoder().decode(encodedImage.toString());
            BufferedImage image = ImageIO.read(new ByteArrayInputStream(imageBytes));
            if (image == null) throw new IllegalStateException("Embedded image could not be decoded.");

            Runnable resizeImage = () -> {
                int availableWidth = imageLabel.getWidth();
                int availableHeight = imageLabel.getHeight();
                if (availableWidth > 0 && availableHeight > 0) {
                    imageLabel.setIcon(new ImageIcon(scaleImage(image, availableWidth, availableHeight)));
                }
            };
            panel.addComponentListener(new java.awt.event.ComponentAdapter() {
                @Override
                public void componentResized(java.awt.event.ComponentEvent e) {
                    resizeImage.run();
                }
            });
            SwingUtilities.invokeLater(resizeImage);
        } catch (Exception ex) {
            imageLabel.setText("Unable to display the embedded pharmacy image.");
            imageLabel.setForeground(MAROON);
            imageLabel.setFont(new Font("Arial", Font.BOLD, 17));
        }
        return panel;
    }

    private Image scaleImage(BufferedImage source, int maxWidth, int maxHeight) {
        double scale = Math.min((double) maxWidth / source.getWidth(),
                (double) maxHeight / source.getHeight());
        int width = Math.max(1, (int) (source.getWidth() * scale));
        int height = Math.max(1, (int) (source.getHeight() * scale));
        return source.getScaledInstance(width, height, Image.SCALE_SMOOTH);
    }

    private void openModule(String[] classNames, String displayName) {
        for (String className : classNames) {
            try {
                Class<?> moduleClass = Class.forName(
                        "com.sarzilsazibpharmacy." + className);
                Constructor<?> constructor = moduleClass.getDeclaredConstructor();
                Object module = constructor.newInstance();

                if (module instanceof Window) {
                    ((Window) module).setVisible(true);
                    return;
                }

                // Supports a module class that exposes a public setVisible(boolean).
                Method setVisible = moduleClass.getMethod("setVisible", boolean.class);
                setVisible.invoke(module, true);
                return;
            } catch (ClassNotFoundException ex) {
                // Try the next known class name.
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(this,
                        "Could not open " + displayName + ".\\n" + ex.getMessage(),
                        "Module Launch Error", JOptionPane.ERROR_MESSAGE);
                return;
            }
        }

        JOptionPane.showMessageDialog(this,
                displayName + " class was not found. Check the class name and package.",
                "Module Not Found", JOptionPane.ERROR_MESSAGE);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new MainDashBoard().setVisible(true));
    }
}